LEGEND_MISSIONS = {}
LEGEND_BRIEFINGS = {}
LEGEND_PATHS = {}
LEGEND_DESCRIPTIONS = {}
LEGEND_RULES = {}
LEGEND_FIELDS = {}

for key, story in ADVENTURES.items():
    acts = story["path"]
    assert len(acts) == 2 and list(map(len, acts)) == [5, 6], key
    assert len(set(acts[0] + acts[1])) == 11, key
    assert len(story["notes"]) == 11, key
    LEGEND_PATHS[key] = acts
    LEGEND_MISSIONS[key] = {
        k: story[k] for k in ("title", "subtitle", "location", "story", "attack_title",
                            "defend_title", "attack_action", "defend_action", "goal",
                            "threats", "defense", "log", "beats", "crisis_name", "crisis_phrase",
                            "crisis_intro", "switch", "win", "lose")
    }
    LEGEND_MISSIONS[key]["commands"] = list(acts[0] + acts[1])
    LEGEND_BRIEFINGS[key] = {k: story[k] for k in ("chapter", "opening", "hacker", "defender", "stakes", "stageObjectives", "outro")}
    LEGEND_DESCRIPTIONS[key] = dict(zip(LEGEND_MISSIONS[key]["commands"], story["notes"]))
    LEGEND_DESCRIPTIONS[key].update({
        phrase: f"{phrase.capitalize()} to protect the team against {story['meter'].lower()} while the other operator advances the rescue."
        for phrase in story["defense"]
    })
    LEGEND_DESCRIPTIONS[key][story["crisis_phrase"]] = story["crisis_intro"]
    options = {}
    for ident, label, description, phrase, effects, outcome in story["choices"]:
        options[ident] = {"label":label,"description":description,"phrase":phrase,"effects":effects,"outcome":outcome}
        LEGEND_DESCRIPTIONS[key][phrase] = description + " " + outcome
    LEGEND_RULES[key] = {"meter":story["meter"],"direction":"high", "initial":19,
                         "hack":6,"defend":-13,"breach":19,"pulse":-13,"warning":67,
                         "warning_text":story["warning_text"],"failure":story["failure"],
                         "intro":story["stakes"],"encounter":story["encounter"],
                         "encounter_intro":story["encounter_intro"],"choices":options}
    LEGEND_FIELDS[key] = tuple({
        "heading":heading,"context":context,
        "options":tuple({"id":i,"label":l,"benefit":b,"effects":e,"outcome":o} for i,l,b,e,o in opt)
    } for heading,context,opt in story["fields"])

